parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json || {};
  const topic = (body.topic || '').trim();
  const format = (body.format || '').trim();
  const contentId = (body.content_id || 'IG-' + new Date().toISOString().slice(2,10).replace(/-/g,'') + '-POST').trim();
  const pillar = (body.content_pillar || 'Pain & Problem').trim();
  const bucket = (body.framework_bucket || '40_Pain').trim();
  const targetAudience = (body.target_audience || 'Coaches & Healers').trim();
  const sourceInsight = (body.source_insight || '').trim();

  const missing = [];
  if (!topic) missing.push('topic');
  if (!format) missing.push('format');

  if (missing.length > 0) {
    results.push({
      json: {
        is_valid: false,
        status: 'THIEU_DU_LIEU',
        missing: missing,
        message: 'Yêu cầu không hợp lệ. Vui lòng cung cấp đầy đủ: ' + missing.join(', ')
      }
    });
  } else {
    results.push({
      json: {
        is_valid: true,
        content_id: contentId,
        topic: topic,
        format: format,
        content_pillar: pillar,
        framework_bucket: bucket,
        target_audience: targetAudience,
        source_insight: sourceInsight
      }
    });
  }
}

return results;

parameters.responseBody:
={{ JSON.stringify({
  status: 'THIEU_DU_LIEU',
  error: true,
  missing: $json.missing,
  message: $json.message
}) }}

parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  let spec;
  try {
    const rawContent = item.json.choices[0].message.content;
    spec = JSON.parse(rawContent);
  } catch(e) {
    spec = item.json;
  }
  results.push({ json: spec });
}

return results;

